#!/usr/bin/env python3
"""Demon Wings elytra-style look (FinalityItems 1.5.11+). Usage: demon-wings-pack.py <plugins dir>
Adds to the Nexo pack folder:
  assets/finality/textures/entity/equipment/wings/demon_wings.png
  assets/finality/equipment/dw_<ns>_<armour>.json  = that chestplate's normal armour look + the Demon Wings layer
for every vanilla chestplate material and every Nexo armour set. Safe to re-run (e.g. after adding new Nexo armour)."""
import base64, json, os, sys, zipfile, re
P = sys.argv[1]
PACK = f"{P}/Nexo/pack"
TEX = ""
os.makedirs(f"{PACK}/assets/finality/textures/entity/equipment/wings", exist_ok=True)
os.makedirs(f"{PACK}/assets/finality/equipment", exist_ok=True)
open(f"{PACK}/assets/finality/textures/entity/equipment/wings/demon_wings.png", "wb").write(base64.b64decode(TEX))
WINGS = [{"texture": "finality:demon_wings"}]
assets = {
    "minecraft:netherite": {"humanoid": [{"texture": "minecraft:netherite"}]},
    "minecraft:diamond": {"humanoid": [{"texture": "minecraft:diamond"}]},
    "minecraft:iron": {"humanoid": [{"texture": "minecraft:iron"}]},
    "minecraft:gold": {"humanoid": [{"texture": "minecraft:gold"}]},
    "minecraft:chainmail": {"humanoid": [{"texture": "minecraft:chainmail"}]},
    "minecraft:copper": {"humanoid": [{"texture": "minecraft:copper"}]},
    "minecraft:leather": {"humanoid": [{"texture": "minecraft:leather", "dyeable": {"color_when_undyed": -6265536}},
                                       {"texture": "minecraft:leather_overlay"}]},
    None: {},
}
# Nexo armour sets: take their layers from the built pack (the 1.21.11 version if there is one)
found = {}
for z in [f for f in os.listdir(PACK) if f.endswith(".zip")]:
    with zipfile.ZipFile(f"{PACK}/{z}") as zz:
        for n in zz.namelist():
            m = re.match(r"^(?:(nexo_[\w]+)/)?assets/([\w.-]+)/equipment/([\w/.-]+)\.json$", n)
            if not m or m.group(3).endswith("_elytra") or m.group(2) == "finality": continue
            key = f"{m.group(2)}:{m.group(3)}"
            prio = 2 if m.group(1) == "nexo_1_21_11" else (1 if m.group(1) is None else 0)
            if key in found and found[key][0] >= prio: continue
            try: found[key] = (prio, json.loads(zz.read(n)).get("layers", {}))
            except Exception: pass
for root, _, files in os.walk(f"{PACK}/assets"):
    for f in files:
        m = re.search(r"/assets/([\w.-]+)/equipment$", root)
        if m and f.endswith(".json") and m.group(1) != "finality" and not f[:-5].endswith("_elytra"):
            try: found[f"{m.group(1)}:{f[:-5]}"] = (3, json.load(open(os.path.join(root, f))).get("layers", {}))
            except Exception: pass
for k, (_, layers) in found.items(): assets[k] = layers
n = 0
for key, layers in assets.items():
    out = {k: v for k, v in layers.items() if k != "wings"}
    out["wings"] = WINGS
    name = "dw_none" if key is None else "dw_" + key.replace(":", "_").replace("/", "_")
    json.dump({"layers": out}, open(f"{PACK}/assets/finality/equipment/{name}.json", "w"), indent=1)
    n += 1
print(f"✅ Demon Wings elytra look: texture + {n} armour looks ({', '.join(sorted(k for k in assets if k))})")
